struct ActualOverlapMemory:Memory{mutable J ledger=J::array();explicit ActualOverlapMemory(Child&c):Memory(c){}bool retained(std::uint32_t p,std::size_t n)const{return p<0x02000000u||p>=0x02010000u||(p>=event_packet&&std::uint64_t(p)+n<=event_packet+9u);}void read(std::uint32_t p,std::span<std::byte>b)const override{Memory::read(p,b);if(retained(p,b.size()))ledger.push_back(J{{"kind","read"},{"address",p},{"bytes",b.size()},{"value",pair_hex(b)}});}void write(std::uint32_t p,std::span<const std::byte>b)override{const auto before=child.read(p,b.size());Memory::write(p,b);if(retained(p,b.size())){check(!ledger.empty()&&ledger.back().at("kind")=="read"&&ledger.back().at("address")==p,"Missing overlap before read");ledger.erase(ledger.end()-1);ledger.push_back(J{{"kind","write"},{"address",p},{"bytes",b.size()},{"before",pair_hex(before)},{"written",pair_hex(b)}});}}};
